import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"会话与上下文","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/guides/sessions.md","filePath":"zh/kimi-code-cli/guides/sessions.md"}`),a={name:`kimi-code-cli/guides/sessions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="会话与上下文" tabindex="-1">会话与上下文 <a class="header-anchor" href="#会话与上下文" aria-label="Permalink to “会话与上下文”">​</a></h1><p>Kimi Code CLI 把每次对话持久化为一个「会话」，保留消息历史和元数据，可以随时关闭终端后再回来继续。本页介绍如何恢复会话、管理上下文，以及导出和派生会话。</p><h2 id="会话存储" tabindex="-1">会话存储 <a class="header-anchor" href="#会话存储" aria-label="Permalink to “会话存储”">​</a></h2><p>所有会话保存在 <code>$KIMI_CODE_HOME/sessions/</code> 下（默认 <code>~/.kimi-code/sessions/</code>），按工作目录分组存放：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/.kimi-code/</span></span>
<span class="line"><span>├── config.toml</span></span>
<span class="line"><span>├── session_index.jsonl</span></span>
<span class="line"><span>└── sessions/</span></span>
<span class="line"><span>    └── &lt;workDirKey&gt;/</span></span>
<span class="line"><span>        └── &lt;sessionId&gt;/</span></span>
<span class="line"><span>            ├── state.json</span></span>
<span class="line"><span>            └── agents/</span></span>
<span class="line"><span>                ├── main/</span></span>
<span class="line"><span>                │   └── wire.jsonl</span></span>
<span class="line"><span>                └── &lt;subagentId&gt;/</span></span>
<span class="line"><span>                    └── wire.jsonl</span></span></code></pre></div><ul><li><code>state.json</code>：会话标题、创建时间等元数据。</li><li><code>agents/*/wire.jsonl</code>：Agent 事件流，用于会话恢复和回放；同时记录发给模型的请求轨迹（工具 schema、请求参数、MCP 工具清单），便于调试。</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p><code>sessions/</code> 目录下的文件请勿手动编辑，否则可能导致会话无法正常恢复。</p></div><h2 id="启动与恢复会话" tabindex="-1">启动与恢复会话 <a class="header-anchor" href="#启动与恢复会话" aria-label="Permalink to “启动与恢复会话”">​</a></h2><p>每次直接运行 <code>kimi</code> 都会创建新会话。以下方式可以恢复历史会话：</p><p><strong>继续当前目录最近的会话：</strong></p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span></code></pre></div><p><strong>恢复指定会话（通过 ID）：</strong></p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> abc123</span></span></code></pre></div><p><strong>交互式浏览历史会话并选择：</strong></p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">注意</p><p><code>--continue</code> 与 <code>--session</code> 互斥。</p></div><h2 id="在-tui-中切换会话" tabindex="-1">在 TUI 中切换会话 <a class="header-anchor" href="#在-tui-中切换会话" aria-label="Permalink to “在 TUI 中切换会话”">​</a></h2><p>不离开当前终端也可以管理会话，以下斜杠命令仅在 Agent 空闲时可用：</p><ul><li><strong><code>/new</code></strong>（别名 <code>/clear</code>）：切换到新会话，丢弃当前上下文。</li><li><strong><code>/sessions</code></strong>（别名 <code>/resume</code>）：浏览并恢复历史会话。</li><li><strong><code>/fork</code></strong>：派生当前会话（详见下文）。</li><li><strong><code>/title &lt;text&gt;</code></strong>（别名 <code>/rename</code>）：设置会话标题方便识别；不带参数时显示当前标题。</li></ul><h2 id="上下文压缩" tabindex="-1">上下文压缩 <a class="header-anchor" href="#上下文压缩" aria-label="Permalink to “上下文压缩”">​</a></h2><p>对话变长时，Kimi Code CLI 会在上下文接近窗口上限时自动压缩历史消息，释放 token 空间。也可以随时手动触发：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/compact</span></span></code></pre></div><p>压缩时可以附带指引，告诉模型优先保留哪些信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/compact 保留与数据库迁移相关的讨论</span></span></code></pre></div><h2 id="派生会话" tabindex="-1">派生会话 <a class="header-anchor" href="#派生会话" aria-label="Permalink to “派生会话”">​</a></h2><p>想在不破坏当前对话的前提下尝试新思路，使用 <code>/fork</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/fork</span></span></code></pre></div><p>派生后的两个会话彼此独立，互不影响，可以随时通过 <code>/sessions</code> 切回原来的会话。已保存的 <code>/goal</code> 不会复制到派生会话。如果你想在派生会话中进行自主 goal 工作，需要在那里开始一个新 goal。</p><h2 id="导出会话" tabindex="-1">导出会话 <a class="header-anchor" href="#导出会话" aria-label="Permalink to “导出会话”">​</a></h2><p>用 <code>kimi export</code> 把会话打包为 ZIP，适合分享、归档或提交问题反馈：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sessionI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>不传 <code>sessionId</code> 时导出当前目录最近的会话（有交互式确认，加 <code>-y</code> 跳过）。用 <code>-o</code> 指定输出路径：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sessionI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/my-session.zip</span></span></code></pre></div><p>导出包含会话目录下的所有文件，包括诊断日志。全局诊断日志（<code>~/.kimi-code/logs/kimi-code.log</code>）默认也会打包；如不需要，加 <code>--no-include-global-log</code> 排除。</p><p>也可以在 TUI 内导出，无需离开交互界面：</p><ul><li><strong><code>/export-debug-zip</code></strong>：产生与 <code>kimi export</code> 相同的调试 ZIP。</li><li><strong><code>/export-md</code></strong>（别名 <code>/export</code>）：导出为人类可读的 Markdown 对话记录，适合分享或存档。可选接收路径参数；不带参数时写入工作目录下的 <code>kimi-export-&lt;short-id&gt;-&lt;timestamp&gt;.md</code>。</li></ul><p>在 web UI 中，<code>/export</code> 会把当前会话下载为诊断 ZIP。压缩包包含持久化的会话数据、诊断日志，以及记录浏览器关键事件且大小有上限、只含元数据的 <code>logs/kimi-web.jsonl</code>；提示词正文、WebSocket 内容和 console 参数不会写入这份浏览器日志。这里的 web 命令与上面的 TUI <code>/export</code> 别名行为不同。</p><p>浏览器需要先把 ZIP 缓存在内存中再保存，因此 web 导出上限为 64 MiB。更大的会话请使用 <code>kimi export &lt;sessionId&gt;</code> 或 TUI 的 <code>/export-debug-zip</code>。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>导出文件可能包含代码、命令输出和路径等敏感信息，分享前请先确认内容。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/configuration/data-locations.html">数据路径</a> — 会话文件的完整目录结构说明</li><li><a href="/code/docs/kimi-code-cli/reference/kimi-command.html">kimi 命令</a> — <code>--continue</code>、<code>--session</code>、<code>export</code> 等命令的完整参数参考</li></ul>`,41)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};